# -*- coding: utf-8 -*-
"""ESTADO_ATUAL.md — one page, generated from the seal. Never edited by hand.

The README is the ledger (2,000+ lines, 134 seals). A reader from outside, or an AI,
needs one page first: the pin, the gate, what is PROVED, what is NOT, how to reproduce.
Every number below is read from the sealed artifacts at generation time; the
qualitative lines are updated at each custody, beside the numbers, never over them.

Uso:  python tools/gerar_estado_atual.py     (before tools/gerar_portas.py in the chain)
"""
import hashlib
import json
import re
import sys
import urllib.parse
from pathlib import Path

RAIZ = Path(__file__).resolve().parent.parent
import os
# 21/09/2026: o deposito citavel no Zenodo e' LIDO do CITATION.cff (fonte unica), nunca escrito a mao nos geradores
import re as _re_dep
_CFF_DEP = open(os.path.join(str(RAIZ), 'CITATION.cff'), encoding='utf-8').read()
_md_dep = _re_dep.search(r'Zenodo deposit of (v\d{3}), deposited ([\d-]{10}) \(byte-identical to the seal: um\.py sha256 ([0-9a-f]{16})', _CFF_DEP)
_doi_dep = _re_dep.search(r'^doi: "(10\.5281/zenodo\.[0-9]+)"', _CFF_DEP, _re_dep.M)
if not (_md_dep and _doi_dep):
    raise SystemExit('FALHA: CITATION.cff sem o doi ou sem a linha do deposito (Zenodo deposit of vNNN, deposited AAAA-MM-DD ...)')
DEP_V, DEP_DATA, DEP_PIN16 = _md_dep.groups()
DEP_DOI = _doi_dep.group(1)
A3 = "Um (absoluto) — Grande Atrator"
RAW = "https://raw.githubusercontent.com/rotolimiguel-iald/the_boundary/main/"
TRIO = ("propext", "Classical.choice", "Quot.sound")


def raw(rel: str) -> str:
    return RAW + urllib.parse.quote(rel)


def sha16(p: Path) -> str:
    return hashlib.sha256(p.read_bytes()).hexdigest()[:16]


def main() -> int:
    d = RAIZ / A3
    selo = json.loads((d / "um_absoluto_selo.json").read_text(encoding="utf-8"))
    mundo_json = json.loads((d / "um_absoluto.json").read_text(encoding="utf-8"))
    man = json.loads((d / "Lean" / "tgl_kernel_proof_manifest.json").read_text(encoding="utf-8"))
    ar, fmap = man["axiom_report"], man["formal_files_sha256"]
    sujos = sum(1 for v in ar.values() if any(a not in TRIO for a in (v or [])))
    livres = sum(1 for v in ar.values() if not v)
    b = (d / "um.py").read_bytes()
    linhas, nbytes = b.count(b"\n"), len(b)
    pin, mundo, ts = selo["sha256"]["um.py"], selo["result_hash"], selo["timestamp"]
    gate = selo.get("qg_closure_verdict", "?")
    rc = selo.get("rite_checkpoints") or {}
    rodadas = sorted(d.glob("rodadas/rodada_v*_stdout.txt"), key=lambda p: int(re.search(r"v(\d+)", p.name).group(1)))
    ultima = rodadas[-1] if rodadas else None
    versao = re.search(r"v(\d+)", ultima.name).group(1) if ultima else "?"
    std = ultima.read_text(encoding="utf-8", errors="replace") if ultima else ""
    # 02/11/2026 — A GUARDA DO NUMERO (correcao ao lado; o texto antigo fica no .bak desta data).
    # O padrao antigo pedia «N/N teoremas», e a linha do stdout selado e' «teoremas limpos: N/N» —
    # nunca casava. Caia-se entao no fallback «\b(\d{3,4})/(\d{3,4})\b», que pegava o PRIMEIRO par de
    # quatro digitos do arquivo: na v405 isso devolveu 3248/3470, que sao os CENTROS DE VAZIO na pegada
    # do rito V11, publicados como se fossem a escada do kernel em cinco arquivos e nos dois espelhos.
    # (O fallback tambem nao alcancava cinco digitos, logo jamais acharia 10066.) Tres guardas agora:
    #   1. a linha e' lida ancorada pelo nome, sem fallback cego;
    #   2. a escada e' sempre N/N — numerador diferente do denominador PARA;
    #   3. o numero tem de existir no SELO (procedencia), nao so no stdout.
    m = re.search(r"teoremas limpos:\s*(\d+)\s*/\s*(\d+)", std)
    assert m, "linha «teoremas limpos: N/N» nao localizada no stdout selado — PARAR (o numero corrige a frase)"
    assert m.group(1) == m.group(2), (
        "a escada do rito nao e N/N: %s/%s — PARAR (isto nao e uma escada)" % (m.group(1), m.group(2)))
    rito = "%s/%s" % (m.group(1), m.group(2))

    def _colher(o, chave, acc):
        if isinstance(o, dict):
            for k, v in o.items():
                if k == chave and isinstance(v, int):
                    acc.append(v)
                else:
                    _colher(v, chave, acc)
        elif isinstance(o, list):
            for v in o:
                _colher(v, chave, acc)
        return acc

    _nk = sorted(set(_colher(selo, "n_theorems_clean", [])))
    assert not _nk or _nk == [int(m.group(1))], (
        "a escada do stdout (%s) nao confere com o selo (%s) — PARAR" % (m.group(1), _nk))
